def run_case(t: object, holder: object, spec: dict, reached: set) -> dict:
    """One case against `holder`'s function, in a fresh test-owned tree; every host-facing seam a recorder on `t`."""
    import contextlib, dataclasses, json, os, shutil, tempfile
    from pathlib import Path as _P
    from types import SimpleNamespace
    from scripts import workflow_launcher
    calls: list = []
    printed: list = []
    tmp = _P(tempfile.mkdtemp(prefix="syrd426-")).resolve()

    @dataclasses.dataclass(frozen=True)
    class Plan:
        project: str
        owner_user: str
        role_accounts: tuple
        role_worktrees: tuple = ()

    def norm(value):
        if isinstance(value, (list, tuple)):
            return [norm(v) for v in value]
        if isinstance(value, (set, frozenset)):
            return sorted(norm(v) for v in value)
        if isinstance(value, dict):
            return {str(k): norm(v) for k, v in sorted(value.items(), key=lambda kv: str(kv[0]))}
        if isinstance(value, _P):
            return "PATH " + norm(str(value))
        if isinstance(value, str):
            return value.replace(str(tmp), "TMP")
        if isinstance(value, (int, float, bool)) or value is None:
            return value
        if isinstance(value, SimpleNamespace):
            return f"NAMESPACE {getattr(value, 'label', '?')}"
        if dataclasses.is_dataclass(value) and not isinstance(value, type):
            return {type(value).__name__: {f.name: norm(getattr(value, f.name)) for f in dataclasses.fields(value)}}
        if value is runner:
            return "RUNNER"
        if value is show:
            return "PRINT"
        if callable(value) and "run_case.<locals>" in getattr(value, "__qualname__", ""):
            return "STAND-IN"
        if callable(value):
            return f"CALLABLE {getattr(value, '__module__', '?')}.{getattr(value, '__qualname__', '?')}"
        return repr(value)

    def note(seam, /, *args, **kwargs):
        reached.add(seam)
        calls.append([seam, norm(list(args)), norm(dict(kwargs))])

    def show(line):
        printed.append(norm(line))

    def runner(argv, **kwargs):
        note("runner", list(argv), **kwargs)
        argv = list(argv)
        if argv[1:] == ["-v"]:  # the credential refresh, matched on its distinguishing argument
            code, err = spec.get("refresh", (0, ""))
            return SimpleNamespace(returncode=code, stdout="", stderr=err)
        if "bash" in argv:
            return SimpleNamespace(returncode=spec.get("bash", 0), stdout="", stderr="")
        raise AssertionError(f"the runner was asked something no case expects: {argv}")

    place = lambda v: (tmp / v[2:]) if isinstance(v, str) and v.startswith("@/") else v
    names = [*FUNCTIONS, "_repo_root", "load_project_design_artifact", "_default_new_project_owner", "_default_role_cli_pairs", "seed_director_onboarding",
             "_load_json", "resolve_control_user", "invoking_human", "build_plan", "precheck_new_project", "_write_json_atomic", "_new_project_worktree_base",
             "write_artifacts", "render_privileged_artifacts", "install_privileged_artifacts", "write_new_project_launcher_artifacts", "load_project_config",
             "role_isolation_gaps", "publish_role_account_migration", "_rollout_recorder_path", "configure_project_desktop", "WORKTREE_POLICIES",
             "DEFAULT_PROJECT_IMPLEMENTER_ROLES"]
    saved = {n: getattr(t, n) for n in names}
    saved_assign, saved_geteuid = workflow_launcher.assign_projection_owner, os.geteuid
    try:
        for d in ("repo", "src", "home/p426"):
            (tmp / d).mkdir(parents=True)
        for name, content in spec.get("files", {}).items():
            (tmp / name).write_text(json.dumps(content), encoding="utf-8")
        if "artifact" in spec and not (tmp / "artifact.json").exists():
            (tmp / "artifact.json").write_text("{}", encoding="utf-8")
        under = {n: getattr(holder, n) for n in FUNCTIONS}

        def load_artifact(path, *, expected_project):
            note("load_project_design_artifact", path, expected_project=expected_project)
            art = spec["artifact"]
            if art == "refuse":
                raise SystemExit("team-launcher: syrd426 artifact refused")
            return SimpleNamespace(**{k: place(v) for k, v in art.items()})

        def plan_for(**kwargs):
            note("build_plan", **kwargs)
            roles = tuple((r, f"{kwargs['owner_user']}-{r}") for r in ("director", *kwargs["implementer_roles"]))
            return Plan(project=kwargs["project"], owner_user=kwargs["owner_user"], role_accounts=roles)

        def precheck(plan, **kwargs):
            note("precheck_new_project", plan, **kwargs)
            if spec.get("precheck") == "refuse":
                raise SystemExit("team-launcher: new project precheck failed:\n- syrd426 port in use")

        def write_artifacts(plan, artifact_dir, **kwargs):
            note("write_artifacts", plan, artifact_dir, **kwargs)
            artifact_dir.mkdir(parents=True, exist_ok=True)
            (artifact_dir / "operator-commands.sh").write_text("#!/bin/bash\n# syrd426 packet\n", encoding="utf-8")

        def install(plan, rendered):
            note("install_privileged_artifacts", plan, rendered)
            if spec.get("install") == "oserror":
                raise OSError(13, "Permission denied")
            return tmp / "root-mirror"

        def launcher_artifacts(plan, artifact_dir, **kwargs):
            note("write_new_project_launcher_artifacts", plan, artifact_dir, **kwargs)
            return artifact_dir / "p426.json"

        def load_config(project, path):
            note("load_project_config", project, path)
            if spec.get("config") == "refuse":
                raise SystemExit("team-launcher: syrd426 config unreadable")
            return SimpleNamespace(label="config", desktop_access={"mode": "wayland"} if spec.get("desktop") else None)

        def publish(config, *, config_path, print_func):
            note("publish_role_account_migration", config, config_path=config_path, print_func=print_func)
            return (tmp / "migrate.sh", []) if spec.get("published") else (None, ["syrd426: no root-owned place"])

        def seed(workflow, repository):
            note("seed_director_onboarding", workflow, repository)
            return ({"seeded": workflow}, [])

        def passthrough(name):
            def f(*args, **kwargs):
                note(name, *args, **kwargs)
                return saved[name](*args, **kwargs)
            return f
        on_launcher = {
            "_repo_root": lambda: note("_repo_root") or tmp / "src",
            "load_project_design_artifact": load_artifact,
            "_default_new_project_owner": passthrough("_default_new_project_owner"),
            "_default_role_cli_pairs": passthrough("_default_role_cli_pairs"),
            "seed_director_onboarding": seed,
            "_load_json": passthrough("_load_json"),
            "resolve_control_user": lambda project, *, invoking_user, owner_user: note("resolve_control_user", project, invoking_user=invoking_user,
                                                                                         owner_user=owner_user) or "p426-control",
            "invoking_human": lambda: note("invoking_human") or "p426-human",
            "build_plan": plan_for,
            "precheck_new_project": precheck,
            "_write_json_atomic": passthrough("_write_json_atomic"),
            "_new_project_worktree_base": lambda project, owner: note("_new_project_worktree_base", project, owner) or _P("/nonexistent/syrd426/worktrees"),
            "write_artifacts": write_artifacts,
            "render_privileged_artifacts": lambda plan, **kwargs: note("render_privileged_artifacts", plan, **kwargs) or {"rendered": "syrd426"},
            "install_privileged_artifacts": install,
            "write_new_project_launcher_artifacts": launcher_artifacts,
            "load_project_config": load_config,
            "role_isolation_gaps": lambda config: note("role_isolation_gaps", config) or (["gap"] if spec.get("gaps") else []),
            "publish_role_account_migration": publish,
            "_rollout_recorder_path": lambda: note("_rollout_recorder_path") or (_P("/nonexistent/syrd426/record") if spec.get("recorder") else None),
            "configure_project_desktop": lambda config, **kwargs: note("configure_project_desktop", config, **kwargs),
            "_new_project_artifact_dir": lambda project: note("_new_project_artifact_dir", project) or tmp / "auto-dir",
            "recorded_provisioning_command": passthrough("recorded_provisioning_command"),
            "new_project_command": passthrough("new_project_command"),
        }
        on_launcher.update(spec.get("launcher", {}))
        for n, f in on_launcher.items():
            setattr(t, n, f)
        workflow_launcher.assign_projection_owner = lambda config, config_path, *, runner: note("assign_projection_owner", config, config_path, runner=runner)
        os.geteuid = lambda: spec.get("euid", 1426)
        call = spec["call"]
        try:
            with contextlib.redirect_stdout(SimpleNamespace(write=lambda s: printed.append(["stdout", norm(s)]) if s.strip() else None, flush=lambda: None)):
                if call == "new":
                    kwargs = {k: (place(v.strip()).__str__() if k == "upstream_report_token_file" else place(v)) for k, v in spec["kwargs"].items()}
                    if "upstream_report_token_file" in kwargs:
                        kwargs["upstream_report_token_file"] = " " + kwargs["upstream_report_token_file"] + " "
                    got = under["new_project_command"]("p426", runner=runner, port_in_use=lambda port: note("port_in_use", port) or False,
                                                       socket_exists=lambda path: note("socket_exists", path) or False, print_func=show, **kwargs)
                elif call == "main":
                    got = t.main([str(place(a)) for a in spec["argv"]])
                elif call == "recorded":
                    got = under["recorded_provisioning_command"]("p426", str(place(spec["script"])))
                else:
                    made = under["_new_project_artifact_dir"]("p426")
                    got = {"parent is the system temp dir": made.parent == _P(tempfile.gettempdir()), "prefix": made.name.startswith("p426-team-launcher-new."),
                           "a new empty directory": made.is_dir() and not any(made.iterdir())}
                    shutil.rmtree(made)
            result = norm(got)
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- the baseline's own answer, whatever it raises
            result = {"raised": type(exc).__name__, "message": norm(str(exc))}
        files = {}
        for path in sorted(tmp.rglob("*")):
            if path.is_file():
                mode = oct(path.stat().st_mode & 0o777) if path.name == "desktop-policy.json" else "per umask"
                files[norm(str(path))] = [mode, norm(path.read_text(encoding="utf-8"))]
        return {"result": result, "calls": calls, "printed": printed, "files": files}
    finally:
        os.geteuid = saved_geteuid
        workflow_launcher.assign_projection_owner = saved_assign
        for n, f in saved.items():
            setattr(t, n, f)
        shutil.rmtree(tmp)
