def test_either_import_order_gives_one_set_of_objects_and_the_launchers_defaults() -> None:
    for order in (("scripts.new_project_command", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.new_project_command")):
        result = python("import builtins, importlib, inspect, subprocess; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.new_project_command as m; "
                        "p = inspect.signature(m.new_project_command).parameters; "
                        f"print(all(getattr(t, n) is getattr(m, n) for n in {MOVED!r}), "
                        "p['port_in_use'].default is t._tcp_port_in_use and p['socket_exists'].default is t._path_exists "
                        "and p['runner'].default is subprocess.run and p['print_func'].default is builtins.print, "
                        "[n for n in ('recorded_provisioning_command', '_new_project_artifact_dir') "
                        "if any(v.default is not inspect.Parameter.empty for v in inspect.signature(getattr(m, n)).parameters.values())], "
                        "not hasattr(m, 'launcher'))")
        check(result.stdout.strip() == "True True [] True", f"{' then '.join(order)}: {result.stdout}{result.stderr[-600:]}")
    from scripts import new_project_precheck
    check(m._tcp_port_in_use is new_project_precheck._tcp_port_in_use and m._path_exists is new_project_precheck._path_exists,
          "the probe defaults come from the module the launcher imports them from")
    check(m.json is json and m.os is os and m.subprocess is subprocess and m.Path is Path, "the standard-library names are the module's own")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "new_project_command.py").read_text(encoding="utf-8"))
    for name in FUNCTIONS:
        node = next(n for n in tree.body if getattr(n, "name", None) == name)
        through: dict[str, int] = {}
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
                through[x.attr] = through.get(x.attr, 0) + 1
        expected = SEAMS.get(name, {})
        check(through == expected, f"{name}: each launcher name read through it exactly as often as before: {through}")
        imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
        first = 1 if ast.get_docstring(node) is not None else 0
        # The command's two call-time imports of other modules stay exactly where the baseline had them.
        nested = {"new_project_command": ["from scripts.desktop_access import validate_policy", "from scripts.workflow_launcher import assign_projection_owner"]}
        check(imports[:1] == (["from scripts import team_launcher as launcher"] if expected else [])
              and sorted(imports[1:] if expected else imports) == sorted(nested.get(name, []))
              and (not expected or ast.unparse(node.body[first]) == imports[0]),
              f"{name}: the launcher imported first thing when it reads one, and otherwise only the baseline's own nested imports: {imports}")
        skip = {id(y) for part in [node.returns, *(a.annotation for a in node.args.args + node.args.kwonlyargs), *[d for d in node.args.kw_defaults if d]]
                if part is not None for y in ast.walk(part)}
        bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected and id(x) not in skip})
        check(bare == [], f"{name}: none of them read past it: {bare}")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    tc = [ast.unparse(n) for n in tree.body if isinstance(n, ast.If)]
    check(top == ["from __future__ import annotations", "import json", "import os", "import shlex", "import subprocess", "import tempfile",
                  "from dataclasses import replace", "from pathlib import Path", "from typing import Any, Callable, Mapping",
                  "from scripts.new_project_precheck import _path_exists, _tcp_port_in_use"] and tc == [],
          f"the standard library and the probe defaults' own module, and no TYPE_CHECKING block: {top} {tc}")
    names = [n.name if isinstance(n, ast.FunctionDef) else n.targets[0].id for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))]
    check(names == list(MOVED), f"the three in the launcher's order, and nothing else: {names}")


def test_the_launcher_reexports_the_three_and_its_readers_reach_them_there() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.new_project_command"]
    check(len(imports) == 1 and sorted(a.name for a in imports[0].names) == sorted(MOVED) and all(a.asname is None for a in imports[0].names),
          "one explicit import of exactly the three, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))),
          "at the top, above every definition and constant that could read them")
    defined = {getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    check(not defined & set(MOVED) and {"main", "_build_parser", "WORKTREE_POLICIES", "_repo_root", "_load_json", "_default_role_cli_pairs",
                                        "_write_json_atomic", "load_project_config", "_rollout_recorder_path", "_default_new_project_owner",
                                        "_new_project_worktree_base", "role_isolation_gaps", "DEFAULT_PROJECT_IMPLEMENTER_ROLES", "_path_exists",
                                        "_tcp_port_in_use", "build_plan", "configure_project_desktop", "install_privileged_artifacts", "invoking_human",
                                        "load_project_design_artifact", "precheck_new_project", "publish_role_account_migration",
                                        "render_privileged_artifacts", "resolve_control_user", "seed_director_onboarding", "write_artifacts",
                                        "write_new_project_launcher_artifacts"} <= defined | exported,
          "the launcher defines none of them, and keeps its neighbours and every seam and default they read, its own or re-exported")
    uses: dict = {}
    for fn in tree.body:
        if isinstance(fn, (ast.FunctionDef, ast.ClassDef)):
            for x in ast.walk(fn):
                if isinstance(x, ast.Name) and x.id in MOVED:
                    uses.setdefault(fn.name, {}).setdefault(x.id, 0)
                    uses[fn.name][x.id] += 1
    check(uses == DISPATCH, f"main dispatches new by its launcher global, exactly as often as before: {uses}")
    loose = sorted({x.id for n in tree.body if not isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Import, ast.ImportFrom)) for x in ast.walk(n)
                    if isinstance(x, ast.Name) and x.id in MOVED})
    check(loose == [], f"and nothing at module level reads them: {loose}")
    for path, uses in READERS.items():
        source = ast.parse((ROOT / path).read_text(encoding="utf-8"))
        got = sorted(ast.unparse(x) for x in ast.walk(source) if (isinstance(x, ast.Attribute) and x.attr in MOVED) or (isinstance(x, ast.Name) and x.id in MOVED))
        check(got == uses, f"{path} still reads them through the launcher: {got}")


