def test_every_answer_is_the_baselines() -> None:
    check(sorted(CASES) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, spec in CASES.items():
        for holder in (m, t):
            got = run(holder, spec)
            check(got == GOLDEN[label], f"{label} ({holder.__name__}): the baseline's answer, every call in order: {got}")


def test_the_rules_hold_in_the_measured_record() -> None:
    def result(label):
        return GOLDEN[label]["result"]

    def seams(label):
        return [c[0] for c in GOLDEN[label]["calls"]]

    def kw(label, seam):
        return next(c[2] for c in GOLDEN[label]["calls"] if c[0] == seam)

    check(result("new: no repository and no artifact")["message"] == "team-launcher: new project requires --repository for the project's working checkout"
          and result("new: an artifact and an owner")["message"] == result("new: an artifact and a repository")["message"]
          == "team-launcher: --from owns owner/repository answers; do not also pass --owner-user or --repository"
          and result("new: execute and dry run together")["message"] == "team-launcher: --execute and --dry-run are mutually exclusive"
          and result("new: a worktree policy nobody offers")["message"] == "team-launcher: worktree policy must be one of ['isolated', 'shared']",
          "the refusals, word for word")
    check("build_plan" not in seams("new: the precheck refuses")[seams("new: the precheck refuses").index("precheck_new_project") + 1:]
          and "write_artifacts" not in seams("new: the precheck refuses"), "nothing is written when the precheck refuses")
    dry = "new: a dry run without an artifact"
    order = seams(dry)
    check(order.index("build_plan") < order.index("precheck_new_project") < order.index("write_artifacts")
          < order.index("write_new_project_launcher_artifacts") < order.index("load_project_config") and "runner" not in order,
          f"plan, precheck, artifacts, launcher config, handoff; a dry run runs nothing: {order}")
    check(kw(dry, "precheck_new_project")["require_owner_user"] is False
          and kw("new: execute, not root, unrecorded", "precheck_new_project")["require_owner_user"] is True
          and kw("new: execute, the owner not required", "precheck_new_project")["require_owner_user"] is False,
          "the owner is required when executing, unless the caller says otherwise")
    # Matched on the arguments after the program, which are what distinguish the three runs.
    check([c[1][0][1:] for c in GOLDEN["new: execute, not root, recorded"]["calls"] if c[0] == "runner"]
          == [["-v"], ["/nonexistent/syrd426/record", "p426", "--label", "provisioning", "--", "bash", "TMP/out/operator-commands.sh"]]
          and [c[1][0][1:] for c in GOLDEN["new: execute, not root, unrecorded"]["calls"] if c[0] == "runner"] == [["-v"], ["TMP/out/operator-commands.sh"]],
          "executing: sudo first, then the packet, recorded when the recorder is there")
    check("render_privileged_artifacts" in seams("new: execute as root, staged") and "render_privileged_artifacts" not in seams("new: execute, not root, recorded"),
          "root stages its own copy of the privileged artifacts, nobody else does")
    check("configure_project_desktop" in seams("new: execute with a desktop") and "configure_project_desktop" not in seams("new: execute, not root, recorded")
          and seams("new: execute, not root, recorded")[-1] == "assign_projection_owner", "the desktop only when configured; the projection owner last")
    check(kw("new: a dry run from an artifact", "write_new_project_launcher_artifacts")["role_models"] == {"main": "gpt-5.6-sol"}
          and kw("new: explicit models and efforts win", "write_new_project_launcher_artifacts")["role_models"] == {"app": "o5"},
          "the artifact's models, unless the caller passes its own")
    check(result("the recorded command, no recorder") == "bash 'TMP/out/operator commands.sh'"
          and result("the default artifact directory") == {"a new empty directory": True, "parent is the system temp dir": True, "prefix": True},
          "the two helpers")
    check(result("team-launcher new, through main") == 0 and "new_project_command" in seams("team-launcher new, through main"), "main dispatches to the launcher's name")


def test_every_launcher_seam_is_reached() -> None:
    # Every function the three read is a recorder on the launcher (the three themselves included); the constants are
    # rebound there by their own cases; DEFAULT_PROJECT_IMPLEMENTER_ROLES and WORKTREE_POLICIES change the answer.
    names = {name for reads in SEAMS.values() for name in reads}
    constants = {name for name in names if not callable(getattr(t, name))}
    check(names - constants <= REACHED, f"a recorder on the launcher reached every function: missing {sorted(names - constants - REACHED)}")
    rebound = {name for spec in CASES.values() for name in spec.get("launcher", {})}
    check(constants == rebound == {"WORKTREE_POLICIES", "DEFAULT_PROJECT_IMPLEMENTER_ROLES"}, f"and every constant rebound: {sorted(constants)} {sorted(rebound)}")


STRUCTURE = ("test_the_module_loads_only_where_its_defaults_come_from", "test_either_import_order_gives_one_set_of_objects_and_the_launchers_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_three_and_its_readers_reach_them_there")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"new_project_command_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
